<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { ElMessageBox, ElSelect, ElOption } from 'element-plus'
import PlatformLayout from '../components/PlatformLayout.vue'
import AgentRunTrace from '../components/AgentRunTrace.vue'
import { useApi,money,type Row } from '../composables/useApi'
import { roleNames,type User } from '../types'
const catalog=ref<Row>({NAME:'',DESCRIPTION:'',ENABLED:true})
const {api,act}=useApi(),stats=ref<Row>({}),metrics=ref<Row>({}),profiles=ref<Row[]>([]),users=ref<User[]>([]),busy=ref(false),error=ref(''),runs=ref<Row[]>([])
async function load(){error.value='';try{[stats.value,metrics.value,profiles.value,users.value,catalog.value,runs.value]=await Promise.all([api('/admin/stats'),api('/admin/agent-metrics'),api<Row[]>('/admin/sitters'),api<User[]>('/admin/users'),api('/service-catalog'),api<Row[]>('/admin/agent-runs')])}catch(e){error.value=(e as Error).message}}
async function audit(row:Row,approved:boolean){try{const result=await ElMessageBox.prompt('填写审核意见','审核喂养员',{inputValue:approved?'资料符合平台服务要求':'请补充服务经验和服务范围',inputPattern:/\S/,inputErrorMessage:'请输入审核意见'});busy.value=true;if(await act(()=>api(`/admin/sitters/${row.ACCOUNT_ID}/audit`,'POST',{approved,note:result.value}),'审核已完成'))await load()}catch{/* 取消 */}finally{busy.value=false}}
async function accountStatus(user:User){if(busy.value)return;try{await ElMessageBox.confirm(`确认${user.enabled?'停用':'启用'}用户 ${user.username}？停用会撤销其登录。`,'账户状态');busy.value=true;if(await act(()=>api(`/admin/users/${user.id}/status`,'PATCH',{enabled:!user.enabled}),'账户状态已更新'))await load()}catch{}finally{busy.value=false}}
async function saveCatalog(){busy.value=true;await act(()=>api('/admin/service-catalog','PUT',{name:catalog.value.NAME,description:catalog.value.DESCRIPTION,enabled:catalog.value.ENABLED}),'服务项目已保存');busy.value=false}
onMounted(load)
</script>
<template><PlatformLayout><div class="page-heading"><div><span class="eyebrow">PLATFORM OPERATIONS</span><h1>平台管理</h1><p>审核服务资料，查看真实订单统计与预约助手调用情况。</p></div><el-button @click="load">刷新数据</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="stats-grid"><article v-for="[key,label] in [['users','注册用户'],['orders','服务订单'],['completed','已完成订单'],['pendingSitters','待审核资料'],['openComplaints','待处理投诉']]" :key="key" class="business-card"><p>{{ label }}</p><strong>{{ stats[key!]??'—' }}</strong></article></div><section class="business-card spaced"><h3>喂养员资料审核</h3><el-table :data="profiles" empty-text="暂无资料"><el-table-column prop="DISPLAY_NAME" label="昵称"/><el-table-column prop="BIO" label="服务介绍" min-width="230"/><el-table-column label="参考报价"><template #default="s">{{ money(s.row.PRICE_CENTS) }}</template></el-table-column><el-table-column label="审核状态"><template #default="s">{{ {PENDING:'待审核',APPROVED:'已通过',REJECTED:'未通过'}[s.row.STATUS as 'PENDING'|'APPROVED'|'REJECTED'] }}</template></el-table-column><el-table-column label="操作" min-width="150"><template #default="s"><template v-if="s.row.STATUS==='PENDING'"><el-button text type="primary" :disabled="busy" @click="audit(s.row,true)">通过</el-button><el-button text type="danger" :disabled="busy" @click="audit(s.row,false)">退回</el-button></template><span v-else class="muted">{{ s.row.REVIEW_NOTE }}</span></template></el-table-column></el-table></section><section class="business-card spaced"><h3>服务项目维护</h3><el-form label-position="top" @submit.prevent="saveCatalog"><el-form-item label="项目名称"><el-input v-model="catalog.NAME" maxlength="100"/></el-form-item><el-form-item label="服务内容"><el-input v-model="catalog.DESCRIPTION" type="textarea" :rows="3" maxlength="1000"/></el-form-item><el-form-item label="预约状态"><el-select v-model="catalog.ENABLED"><el-option label="开放预约" :value="true"/><el-option label="暂停新预约" :value="false"/></el-select></el-form-item><p class="muted">当前提供一个日常喂养服务包，报价以喂养员发布的时段为准。修改内容不影响历史订单快照。</p><el-button type="primary" native-type="submit" :loading="busy">保存服务项目</el-button></el-form></section><section class="business-card spaced"><h3>用户列表</h3><el-table :data="users"><el-table-column prop="username" label="用户名"/><el-table-column prop="displayName" label="昵称"/><el-table-column label="角色"><template #default="s">{{ roleNames[s.row.role as keyof typeof roleNames] }}</template></el-table-column><el-table-column label="账户状态"><template #default="s">{{ s.row.enabled?'可用':'已停用' }}</template></el-table-column><el-table-column label="管理"><template #default="s"><el-button text :disabled="busy" @click="accountStatus(s.row)">{{ s.row.enabled?'停用':'启用' }}</el-button></template></el-table-column></el-table></section><section class="business-card spaced"><h3>预约助手观测</h3><div class="metric-line"><span>调用次数：{{ metrics.CALLS??0 }}</span><span>失败次数：{{ metrics.FAILURES??0 }}</span><span>生成草稿：{{ metrics.DRAFTS??0 }}</span><span>平均耗时：{{ Number(metrics.AVG_DURATION_MS??0).toFixed(0) }} ms</span><span>最终响应 Token：{{ Number(metrics.INPUT_TOKENS??0)+Number(metrics.OUTPUT_TOKENS??0) }}</span></div><p class="muted">统计基于实际请求记录；Token 数仅包含最终模型响应，工具调用中间轮次费用需与供应商账单核对。</p></section><section class="business-card spaced"><h3>最近预约助手调用</h3><article v-for="run in runs.slice(0,20)" :key="run.ID"><p>{{ run.CREATED_AT }} · 用户 {{ run.OWNER_ID }} · {{ run.OUTCOME }}</p><AgentRunTrace :run-id="run.ID"/></article><el-empty v-if="!runs.length" description="暂无调用记录"/></section></PlatformLayout></template>
